 using var key=ECDsa.Create(ECCurve.NamedCurves.nistP256);string pub=key.ExportSubjectPublicKeyInfoPem(),priv=key.ExportPkcs8PrivateKeyPem();var tm=new TmLicensePayload(2,"WatchdogTM",Guid.NewGuid(),"Test customer",Security.InstallationId,"Commercial",18,now.AddMinutes(-1),null);var signed=SignTm(tm,priv);Check(Security.License(signed.ToJson(),false,pub).MaximumTemperatureSensors==18,"valid offline TM activation signature");Reject(()=>Security.License(signed.ToJson(),false,pub,"wrong"),"wrong installation rejected");Check(!SignTm(tm with{Product="WatchdogEM"},priv).TryVerify(pub,out _,out _),"wrong product rejected");Check(!new TmLicenseDocument(signed.Payload+"A",signed.Signature).TryVerify(pub,out _,out _),"tampered license rejected");Reject(()=>Security.License("bad",false,pub),"malformed license rejected");var expired=SignTm(tm with{IssuedAtUtc=now.AddDays(-2),ExpiresAtUtc=now.AddDays(-1)},priv).ToJson();Reject(()=>Security.License(expired,false,pub),"expired activation rejected");Check(Security.License(expired,true,pub).MaximumTemperatureSensors==18,"expired license remains readable for continuity");
