 var queueConfig=Rules.Demo();queueConfig.Settings.Simulation=false;var qs=queueConfig.Sensors[0];qs.EmailEnabled=true;qs.Recipients="test@example.invalid";qs.RecoveryEmail=true;var queueStore=new Store(System.IO.Path.Combine(root,"queue.db"));queueStore.Save(queueConfig,"test","queue");var queueEngine=new MonitorEngine(queueConfig,queueStore);queueStore.Observe(qs,"HIGH",true,DateTimeOffset.UtcNow,false);var failedSender=new EmailWorker(queueEngine,(_,_,_,_,_)=>throw new MailKit.Security.AuthenticationException("test"));await failedSender.ProcessOne(CancellationToken.None);Check(queueStore.Emails(queueConfig).Single().Error.Contains("Authentication")&&queueStore.Emails(queueConfig).Single().Attempts==1,"SMTP authentication failure schedules retry");for(int n=0;n<4;n++){queueStore.Write(d=>Store.Run(d,"UPDATE email SET next=$0",Store.Utc(DateTimeOffset.UtcNow.AddSeconds(-1))));await failedSender.ProcessOne(CancellationToken.None);}Check(queueStore.Emails(queueConfig).Single().Status=="Failed","SMTP retries are bounded");queueStore.Write(d=>Store.Run(d,"UPDATE email SET status='Pending',attempts=0,next=$0",Store.Utc(DateTimeOffset.UtcNow)));queueStore.Observe(qs,"HIGH",false,DateTimeOffset.UtcNow,false);string delivered="";var fakeSender=new EmailWorker(queueEngine,(_,_,_,body,_)=>{delivered=body;return Task.CompletedTask;});await fakeSender.ProcessOne(CancellationToken.None);Check(delivered.Contains("has since cleared")&&queueStore.Emails(queueConfig).Any(x=>x.Status=="Submitted to mail server"),"delayed initial email includes observed recovery");await fakeSender.ProcessOne(CancellationToken.None);Check(queueStore.Emails(queueConfig).All(x=>x.Status=="Submitted to mail server"),"recovery submission status persists");queueConfig.Settings.Simulation=true;queueStore.Observe(qs,"HIGH",true,DateTimeOffset.UtcNow,true);int sends=0;await new EmailWorker(queueEngine,(_,_,_,_,_)=>{sends++;return Task.CompletedTask;}).ProcessOne(CancellationToken.None);Check(sends==0,"simulat