 var reminderConfig=Rules.Demo();reminderConfig.Settings.Simulation=false;var rs=reminderConfig.Sensors[0];rs.EmailEnabled=true;rs.Recipients="test@example.invalid";rs.Reminders=true;rs.ReminderMinutes=1;var reminderStore=new Store(System.IO.Path.Combine(root,"reminder.db"));var observed=DateTimeOffset.UtcNow.AddMinutes(-3);reminderStore.Observe(rs,"HIGH",true,observed,false);var lastObserved=reminderStore.Alarms(reminderConfig).Single().LastObserved;reminderStore.QueueDueReminders(reminderConfig,DateTimeOffset.UtcNow);Check(reminderStore.Emails(reminderConfig).Any(x=>x.Kind=="Reminder")&&reminderStore.Alarms(reminderConfig).Single().LastObserved==lastObserved,"outage reminders preserve actual last observation time");
 var serialTransport=new Transport();int concurrent=0,maxConcurrent=0;await Task.WhenAll(Enumerable.Range(0,10).Select(_=>serialTransport.Serialize("COM-shared",async()=>{int current=Interlocked.Increment(ref concurrent);maxConcurrent=Math.Max(maxConcurrent,current);await Task.Delay(10);Interlocked.Decrement(ref concurrent);return true;},CancellationToken.None)));Check(maxConcurrent==1,"shared serial request gate never overlaps");
