 static async Task TcpTest(){var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();using var cancel=new CancellationTokenSource();ushort setpoint=80;int requests=0;var server=Task.Run(async()=>{try{while(!cancel.IsCancellationRequested){using var client=await listener.AcceptTcpClientAsync(cancel.Token);var stream=client.GetStream();while(!cancel.IsCancellationRequested){byte[] h=new byte[7];try{await stream.ReadExactlyAsync(h,cancel.Token);}catch(EndOfStreamException){break;}int length=(h[4]<<8|h[5])-1;var p=new byte[length];await stream.ReadExactlyAsync(p,cancel.Token);int address=p[1]<<8|p[2];requests++;if(p[0] is not (3 or 4)||address!=0)throw new Exception("Only the temperature register may be read");byte[] response=p[0] switch{1=>[1,1,1],2=>[2,1,0],3 or 4=>[p[0],2,(byte)((address==100?setpoint:45)>>8),(byte)(address==100?setpoint:45)],6=>p,_=>throw new Exception("Unexpected function")};if(p[0]==6)setpoint=(ushort)(p[3]<<8|p[4]);h[4]=0;h[5]=(byte)(response.Length+1);await stream.WriteAsync(h,cancel.Token);await stream.WriteAsync(response,cancel.Token);}}}catch(OperationCanceledException){}});try{var c=new Controller{Protocol=Protocol.TCP,Host="127.0.0.1",TcpPort=((IPEndPoint)listener.LocalEndpoint).Port};var s=new Sensor{TemperatureOffset=0,HighAlarmOffset=0,HighLimitOffset=100,Multiplier=.1,LimitMultiplier=.1};var transport=new Transport();var r=await transport.Read(c,s,false,CancellationToken.None);Check(r.Temperature==4.5&&r.High==null&&r.Low==null&&r.HighLimit==null&&!r.Fault&&requests==1,"live FC03 reads only temperature despite legacy alarm mappings");var bare=new Sensor{TemperatureOffset=0,Multiplier=.1,LowAlarmEnabled=true};Check(bare.Mapped,"temperature alone permits monitoring with legacy low alarm enabled");Check((await transport.Read(c,bare,false,CancellationToken.None)).Temperature==4.5,"continuous read requires no PLC alarm or limit mapping");Check(await transport.ReadTemperature(c,bare,CancellationToken.None)==4.5,"read-only connection test needs no alarm or write mappings");s.TemperatureFunction=RegisterFunction.Input04;Check((await transport.Read(c,s,false,CancellationToken.None)).Temperature==4.5,"Modbus TCP loopback FC04");Check(requests==4,"all requests are temperature-only FC03 or FC04 reads");}finally{cancel.Cancel();listener.Stop();await server;}}
 static int Render(){var app=new Application();var c=Rules.Demo();c.Settings.PasswordHash=Security.Hash("local-test-only-password");c.Settings.AudibleAlarm=false;foreach(var s in c.Sensors)s.SampleSeconds=1;var store=new Store(System.IO.Path.Combine(root,"ui.db"));store.Save(c,"test","UI smoke");var window=new MainWindow(store,c);window.Show();var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(4)};timer.Tick+=async(_,_)=>{timer.Stop();try{var tabs=(TabControl)typeof(MainWindow).GetField("tabs",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(window)!;for(int i=0;i<5;i++){tabs.SelectedIndex=i;window.UpdateLayout();var bmp=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);bmp.Render(window);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bmp));using var f=File.Create(System.IO.Path.Combine(root,$"screen-{i+1}.png"));png.Save(f);}foreach(var item in new (object Model,string Name)[]{(new Controller{Protocol=Protocol.RTU,Name="DDC01 · First floor"},"controller-setup"),(new Sensor{Name="Fridge 01",Location="First floor"},"sensor-setup")}){var editor=new Editor(item.Model,"Watchdog TM — Setup"){Owner=window};editor.Show();editor.UpdateLayout();var eb=new RenderTargetBitmap((int)editor.ActualWidth,(int)editor.ActualHeight,96,96,PixelFormats.Pbgra32);eb.Render(editor);var ep=new PngBitmapEncoder();ep.Frames.Add(BitmapFrame.Create(eb));using(var ef=File.Create(System.IO.Path.Combine(root,item.Name+".png")))ep.Save(ef);editor.Close();}var eng=(MonitorEngine)typeof(MainWindow).GetField("engine",BindingFlags.Instance|BindingFlags.NonPublic)!.GetValue(window)!;await eng.Stop();typeof(MainWindow).GetField("closing",BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(window,true);Console.WriteLine("UI renders: "+root);window.Close();app.Shutdown();}catch(Exception ex){Console.WriteLine(ex);app.Shutdown(1);}};timer.Start();return app.Run();}
